#!/usr/bin/env python3
import bisect
import gzip
import pathlib
import sys
from collections import Counter


def opener(path):
    p = pathlib.Path(path)
    if str(p).endswith('.gz'):
        return gzip.open(p, 'rt')
    return open(p, 'rt')


def load_bed(path):
    by_chr = {}
    n = 0
    with opener(path) as fh:
        for line in fh:
            if not line.strip() or line.startswith('#') or line.startswith('track'):
                continue
            f = line.rstrip('\n').split('\t')
            if len(f) < 3:
                continue
            try:
                chrom, start, end = f[0], int(f[1]), int(f[2])
            except ValueError:
                continue
            if end <= start:
                continue
            by_chr.setdefault(chrom, []).append((start, end))
            n += 1
    for chrom in by_chr:
        by_chr[chrom].sort()
    return by_chr, n


